static std::string sanitize_display_name(const std::string& raw) {
    std::string out;
    out.reserve(raw.size());
    for (char c : raw) {
        if (out.empty() && c == '/') { continue; }
        if (c == '[' || c == ']') { continue; }
        if (static_cast<unsigned char>(c) < 0x20 || c == 0x7f) { continue; }
