1142	void ExternalBridge::run_async_ask(
1143	    const std::string& prompt,
1144	    const std::string& task_id,
1145	    int client_fd) {
1146	    {
1147	        std::lock_guard<std::mutex> lock(tasks_mutex_);
1148	        AsyncTask t;
1149	        t.status = "queued";
1150	        t.phase = "queued";
1151	        t.created = std::chrono::steady_clock::now();
1152	        tasks_[task_id] = std::move(t);
1153	    }
1154	
1155	    // gh#59 (v2.3.1): the async-ask worker runs entropic_run on this
1156	    // handle's behalf — scope its logs to the owning handle.
1157	    int log_id = handle_ ? handle_->log_id : 0;
1158	    std::thread([this, prompt, task_id, client_fd, log_id]() {
1159	        entropic::log::HandleLogScope scope(log_id);
1160	        update_task_phase(task_id, "running", "running");
1161	        attach_phase_observer(task_id);
1162	
1163	        char* result_json = nullptr;
1164	        auto err = entropic_run(handle_, prompt.c_str(), &result_json);
1165	
1166	        detach_phase_observer();
1167	
1168	        auto final_state = derive_async_final_state(
1169	            handle_, err, result_json);
1170	
1171	        {
1172	            std::lock_guard<std::mutex> lock(tasks_mutex_);
1173	            auto it = tasks_.find(task_id);
1174	            if (it != tasks_.end()) {
1175	                it->second.status = final_state.status;
1176	                it->second.phase = final_state.phase;
1177	                it->second.result = final_state.text;
1178	            }
1179	            // Issue #12 (v2.1.4): write sentinel UNDER tasks_mutex_,
1180	            // before the MCP notification fires. Any external monitor
1181	            // reacting to the sentinel can immediately call
1182	            // entropic.ask_status and see the same terminal state.
1183	            write_sentinel(task_id, final_state.status);
1184	        }
1185	        auto status = final_state.status;
1186	
1187	        // Issue #4 (v2.1.2, parts A+B): emit the spec-defined
1188	        // ``notifications/progress`` method instead of the previous
1189	        // non-spec ``notifications/ask_complete``. MCP-compliant
1190	        // clients are obligated to drain ``notifications/progress``
1191	        // (it's in the documented set); some clients silently
1192	        // buffered or stalled on the unknown method name, which
1193	        // combined with the bridge's blocking broadcast (fixed in
1194	        // part C of this release) produced the deadlock observed
1195	        // against entropic-explorer ↔ Claude Code in the field.
1196	        //
1197	        // ``progressToken`` is the ``task_id`` so the consumer can
1198	        // correlate the notification back to the originating
1199	        // ``entropic.ask`` response (which carried the same
1200	        // ``task_id``). The result body is NO LONGER shipped inline
1201	        // — consumers fetch via ``entropic.ask_status``. This caps
1202	        // notification size at ~200 bytes regardless of generated
1203	        // output, eliminating a real DoS surface (a 50KB result
1204	        // would otherwise flood the broadcast write path on every
1205	        // subscriber). ``status`` rides in ``message`` so consumers
1206	        // can branch on done / error / cancelled without an extra
1207	        // round-trip just to learn which result kind to fetch.
1208	        json notif = {
1209	            {"jsonrpc", "2.0"},
1210	            {"method", "notifications/progress"},
1211	            {"params", {
1212	                {"progressToken", task_id},
1213	                {"progress", 100},
1214	                {"total", 100},
1215	                {"message", status}
1216	            }}
1217	        };
1218	        broadcast_notification(notif);
